  merge into road_contract c
  using (select 1 contract_id from dual) s on (c.contract_id = s.contract_id)
  when matched then update set contract_version = '0.1.0', document = l_doc, loaded_at = systimestamp
  when not matched then insert (contract_id, contract_version, document) values (1, '0.1.0', l_doc);
  commit;
end;
